    return True

def get_chromatic_number(G):
    # For small graphs, we can use nx.coloring.greedy_color
    # But that's an approximation. Let's use a better way.
    # For 15 vertices, we can use backtracking or just check if it's 5-colorable.
    # Actually, nx.coloring.greedy_color is not guaranteed to be optimal.
    # Let's use a simple backtracking algorithm for chromatic number.

    def is_valid(node, color, coloring):
        for neighbor in G.neighbors(node):
            if coloring.get(neighbor) == color:
                return False
        return True

    def solve(node_idx, coloring, num_colors):
        if node_idx == len(G.nodes()):
            return True
        node = list(G.nodes())[node_idx]
        for color in range(num_colors):
            if is_valid(node, color, coloring):
                coloring[node] = color
                if solve(node_idx + 1, coloring, num_colors):
                    return True
                del coloring[node]
        return False

    for num_colors in range(1, 6):
        if solve(0, {}, num_colors):
            return num_colors
    return 6

