# A bipartite graph is always triangle-free.
# Let's create a bipartite graph with 7 and 8 vertices.
# A complete bipartite graph K_{7,8} has 7*8 = 56 edges.
# We need degree >= 3.
# Let's take a random subgraph of K_{7,8} with enough edges.
import random

def generate_bipartite_graph():
    while True:
        G = nx.Graph()
        G.add_nodes_from(range(15))
        # Partition into 7 and 8
        part1 = list(range(7))
        part2 = list(range(7, 15))

        # Add edges randomly
        edges = []
        for u in part1:
            for v in part2:
                if random.random() < 0.5:
                    edges.append((u, v))
        G.add_edges_from(edges)

        if all(d >= 3 for _, d in G.degree()) and is_triangle_free(G):
            return G

for _ in range(1000):
    G = generate_bipartite_graph()
    # Bipartite graphs are 2-colorable, so chromatic number is 2 <= 5.
    print("Found!")
    print(list(G.edges()))
